#!/bin/bash
set -eu
sudo python3 -I -S -B - <<'MONTHLY_CONTENT_CAPTURE'
import base64,hashlib,json,os,re,resource,socket,sys,zlib
try:
 sys.dont_write_bytecode=True;os.umask(0o077);resource.setrlimit(resource.RLIMIT_CORE,(0,0))
 if os.geteuid()!=0 or socket.gethostname()!='iZj6c4cj7edgnhdimts4l7Z':raise RuntimeError('EXACT_ROOT_SERVER_REQUIRED')
 body=zlib.decompress(base64.b64decode('',validate=True))
 if len(body)!=9174 or hashlib.sha256(body).hexdigest()!='e7df079112d11603114c4acb7dc1917b59983b25af0544c583d5a39c0686445f':raise RuntimeError('EXACT_READONLY_PREFLIGHT_BYTES_REQUIRED')
 namespace={'__name__':'reviewed_monthly_content_capture','__file__':'<reviewed-monthly-content-capture>'}
 exec(compile(body,namespace['__file__'],'exec'),namespace);print(json.dumps(namespace['capture'](),sort_keys=True))
except BaseException as error:
 value=str(error);code=value if re.fullmatch('[A-Z][A-Z0-9_]{0,95}',value) else 'MONTHLY_CONTENT_PREFLIGHT_REJECTED'
 print(json.dumps({'stage':'MONTHLY_CONTENT_PREFLIGHT_REJECTED','code':code}));sys.exit(1)
MONTHLY_CONTENT_CAPTURE
